import numpy as np

# 逐层前向传播的简化实现
def sigmoid(x):
    return 1 / (1 + np.exp(-x))

class SimpleLayer:
    def __init__(self, w, b):
        self.w = w
        self.b = b

    def forward(self, x):
        # 单层前向传播：a = f(w x + b)
        return sigmoid(self.w @ x + self.b)

# 随机初始化两层
W1, b1 = np.random.randn(4, 3), np.zeros(4)
W2, b2 = np.random.randn(1, 4), np.zeros(1)

x = np.random.randn(3)
h = SimpleLayer(W1, b1).forward(x)   # 第一层输出
y = SimpleLayer(W2, b2).forward(h)   # 第二层输出
print(y)

