quiz.starterCode:
import numpy as np

def dL_dw(X, a, Y):
    pass

quiz.solution:
import numpy as np

def dL_dw(X, a, Y):
    da_dz = a * (1 - a)
    dL_da = 2 * (a - Y) / len(X)
    return np.sum(dL_da * da_dz * X)

