def rnn_step(x_t, h_prev, W_x, W_h, b):
    pass

quiz.solution:
import numpy as np

def rnn_step(x_t, h_prev, W_x, W_h, b):
    return np.tanh(W_x @ x_t + W_h @ h_prev + b)
